-- Explicit Data API access: compatible with the 2026-10-30 Supabase defaults.
-- Audited grants preserve application/RLS access on clean replay. No row changes.
-- Absent objects belong to pending releases; this migration does not deploy them.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public","doctor_private" REVOKE ALL ON TABLES FROM PUBLIC,anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public","doctor_private" REVOKE ALL ON SEQUENCES FROM PUBLIC,anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public","doctor_private" REVOKE ALL ON FUNCTIONS FROM PUBLIC,anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

DO $access$
DECLARE item record;
BEGIN
  FOR item IN SELECT * FROM (VALUES
    ('public','audit_events_id_seq','SEQUENCE','SELECT,UPDATE,USAGE','anon'),
    ('public','audit_events_id_seq','SEQUENCE','SELECT,UPDATE,USAGE','authenticated'),
    ('public','audit_events_id_seq','SEQUENCE','SELECT,UPDATE,USAGE','service_role'),
    ('public','doctor_profiles','TABLE','SELECT','authenticated'),
    ('public','doctor_profiles','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','practices','TABLE','SELECT','authenticated'),
    ('public','practices','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','onboarding_drafts','TABLE','SELECT','authenticated'),
    ('public','onboarding_drafts','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','secretary_invitations','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','locations','TABLE','SELECT','authenticated'),
    ('public','locations','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','audit_events','TABLE','SELECT','authenticated'),
    ('public','audit_events','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','memberships','TABLE','SELECT','authenticated'),
    ('public','memberships','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','membership_locations','TABLE','SELECT','authenticated'),
    ('public','membership_locations','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','patient_identities','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','practice_patients','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','patient_administrative_activity','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','patient_administrative_activity_id_seq','SEQUENCE','SELECT,UPDATE,USAGE','service_role'),
    ('public','patient_documents','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','patient_document_versions','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','patient_document_events','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','patient_document_events_id_seq','SEQUENCE','SELECT,UPDATE,USAGE','service_role'),
    ('public','location_schedules','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','appointment_events','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','appointment_events_id_seq','SEQUENCE','SELECT,UPDATE,USAGE','service_role'),
    ('public','appointments','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','appointment_queue_revisions','TABLE','SELECT','authenticated'),
    ('public','appointment_queue_revisions','TABLE','DELETE,INSERT,MAINTAIN,REFERENCES,SELECT,TRIGGER,TRUNCATE,UPDATE','service_role'),
    ('public','account_profiles','TABLE','SELECT','authenticated'),
    ('public','doctor_privacy_requests','TABLE','SELECT','authenticated')
  ) AS allowed(schema_name,object_name,object_kind,privileges,role_name) LOOP
    IF to_regclass(format('%I.%I',item.schema_name,item.object_name)) IS NOT NULL THEN
      EXECUTE format('GRANT %s ON %s %I.%I TO %I',item.privileges,item.object_kind,item.schema_name,item.object_name,item.role_name);
    END IF;
  END LOOP;
  FOR item IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname=ANY(ARRAY['public','doctor_private']::text[]) AND c.relkind IN ('r','p','v','m')
  LOOP
    EXECUTE format('REVOKE TRUNCATE,REFERENCES,TRIGGER ON TABLE %I.%I FROM PUBLIC,anon,authenticated',item.nspname,item.relname);
    IF current_setting('server_version_num')::integer>=170000 THEN
      EXECUTE format('REVOKE MAINTAIN ON TABLE %I.%I FROM PUBLIC,anon,authenticated',item.nspname,item.relname);
    END IF;
  END LOOP;
END $access$;

